package com.simon.harmonichackernews.benchmark

import com.simon.harmonichackernews.palette.HarmonicPalette
import com.simon.harmonichackernews.palette.HarmonicPaletteSwatch
import com.simon.harmonichackernews.settings.PreviewTintPolicy
import java.security.MessageDigest
import androidx.test.platform.app.InstrumentationRegistry

/** Captured from the former library before its removal; never generated by these tests. */
internal val paletteGoldens: Map<String, String> by lazy {
    InstrumentationRegistry.getInstrumentation().context.assets.open("palette-goldens.txt")
        .bufferedReader().useLines { lines ->
            lines.filter { it.isNotBlank() && !it.startsWith("#") }
                .associate { it.substringBeforeLast('=') to it.substringAfterLast('=') }
        }
}

/** Stable SHA-256 over sampled pixels, ordered swatches, exact HSL bits, targets, and final tints. */
internal fun paletteGolden(pixels: IntArray?, palette: HarmonicPalette): String {
    val digest = MessageDigest.getInstance("SHA-256")
    fun add(value: Int) {
        repeat(4) { digest.update((value ushr (it * 8)).toByte()) }
    }
    fun swatch(value: HarmonicPaletteSwatch?) {
        add(if (value == null) 0 else 1)
        if (value != null) {
            add(value.rgb); add(value.population)
            add(value.hue.toBits()); add(value.saturation.toBits()); add(value.lightness.toBits())
        }
    }
    add(pixels?.size ?: -1)
    pixels?.forEach { add(it) }
    add(palette.swatches.size)
    palette.swatches.forEach { swatch(it) }
    listOf(palette.dominant, palette.lightVibrant, palette.vibrant, palette.darkVibrant,
        palette.lightMuted, palette.muted, palette.darkMuted).forEach { swatch(it) }
    for (base in listOf(0xfff8f7f4.toInt(), 0xff151515.toInt())) {
        for (mode in listOf("default", "vibrant", "dominant")) {
            for (settings in listOf("100|110|0", "0|0|-20", "200|200|20")) {
                add(PreviewTintPolicy.calculateCardTint(base, palette.toPreviewTintPalette(), "$mode|$settings"))
            }
        }
    }
    return digest.digest().joinToString("") { "%02x".format(it) }
}
